SET NAMES utf8mb4;

DELETE FROM maintenance_history
WHERE mileage IN (1000,3000,6000,9000,12000,15000,18000,21000,24000)
   OR (motorcycle_id = 26 AND mileage = 8500)
   OR (motorcycle_id = 29 AND mileage = 4200)
   OR (motorcycle_id = 35 AND mileage = 7300);


-- Keep each motorcycle's service schedule in sync with its history
